const menu=document.querySelector('#menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','메뉴 열기');}));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button);});document.querySelectorAll('.look').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter);}));
const notes={navy:'네이비 재킷에 밝은 니트와 팬츠를 매치해 보세요. 단정한 색의 대비가 격식을 살리면서도 편안한 인상을 만들어줍니다.',olive:'차분한 올리브 톤과 베이지 계열을 함께 입어보세요. 자연스러운 색의 조화로 주말의 산책과 가벼운 외출에 여유를 더합니다.',blue:'밝은 블루 재킷에 화이트 계열 이너를 더해보세요. 색을 간결하게 맞추면 산뜻하면서도 정돈된 스타일을 즐길 수 있습니다.'};const dialog=document.querySelector('dialog');document.querySelectorAll('.look').forEach(card=>card.addEventListener('click',()=>{const img=card.querySelector('img');document.querySelector('#detail-img').src=img.src;document.querySelector('#detail-img').alt=img.alt;document.querySelector('#detail-title').textContent=card.querySelector('h3').textContent;document.querySelector('#detail-text').textContent=notes[card.dataset.look];dialog.showModal();}));document.querySelectorAll('.close,.close-bottom').forEach(b=>b.addEventListener('click',()=>dialog.close()));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
